sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 anchor;
uniform float zoomFrom;
uniform float zoomTo;
uniform float zoomTime;
uniform float easing;
uniform float loop;
uniform float panX;
uniform float panY;
uniform float transparentEdge;
uniform float shutter;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float4 texT(float2 p) {
    return float4(image.eval(p));
}
float4 smp(float2 p, float tr) {
    return tr > 0.5 ? texT(p) : tex(p);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float4 shot(float2 coord, float T) {
    float u = T / max(zoomTime, 0.01);
    if (loop < 0.5) u = saturate(u);
    else if (loop < 1.5) u = fract(u);
    else {
        u = mod(u, 2.0);
        u = u > 1.0 ? 2.0 - u : u;
    }
    if (easing > 0.5 && easing < 1.5) u = u * u * (3.0 - 2.0 * u);
    else if (easing > 1.5 && easing < 2.5) u = 1.0 - (1.0 - u) * (1.0 - u);
    else if (easing > 2.5) u = u * u;
    float z = mix(zoomFrom, zoomTo, u);
    float2 anc = anchor * size;
    float2 q = anc + (coord - anc - float2(panX, panY) * u) / z;
    return smp(q, transparentEdge);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float4 acc = float4(0.0);
    for (int i = 0; i < 8; i++) {
        acc += shot(coord, time - shutter * 0.04 * float(i) / 7.0);
    }
    return fin(c, acc / 8.0, opacity);
}
